UPDATE blogappdb.tb_post
SET categoria_id = CASE id

    -- 1. Deploy na sexta-feira é relativo
    WHEN '10000000-0000-0000-0000-000000000001'
        THEN '30000000-0000-0000-0000-000000000002'

    -- 2. Git: o inconsciente do desenvolvedor
    WHEN '10000000-0000-0000-0000-000000000002'
        THEN '30000000-0000-0000-0000-000000000003'

    -- 3. A sombra do código legado
    WHEN '10000000-0000-0000-0000-000000000003'
        THEN '30000000-0000-0000-0000-000000000004'

    -- 4. O teste de Turing encontrou um bug
    WHEN '10000000-0000-0000-0000-000000000004'
        THEN '30000000-0000-0000-0000-000000000005'

    -- 5. Ada encontra um bug moderno
    WHEN '10000000-0000-0000-0000-000000000005'
        THEN '30000000-0000-0000-0000-000000000001'

    -- 6. Docker funciona... mas no meu computador
    WHEN '10000000-0000-0000-0000-000000000006'
        THEN '30000000-0000-0000-0000-000000000006'

    -- 7. A terceira lei do deploy
    WHEN '10000000-0000-0000-0000-000000000007'
        THEN '30000000-0000-0000-0000-000000000002'

    -- 8. Só sei que meu código funciona
    WHEN '10000000-0000-0000-0000-000000000008'
        THEN '30000000-0000-0000-0000-000000000001'

    -- 9. Eppur si deploya
    WHEN '10000000-0000-0000-0000-000000000009'
        THEN '30000000-0000-0000-0000-000000000006'

    -- 10. A essência de um projeto legado
    WHEN '10000000-0000-0000-0000-000000000010'
        THEN '30000000-0000-0000-0000-000000000004'

    -- 11. Deploy de sexta às 17:59
    WHEN '10000000-0000-0000-0000-000000000011'
        THEN '30000000-0000-0000-0000-000000000002'

    -- 12. Aprovou meu PR sem ler
    WHEN '10000000-0000-0000-0000-000000000012'
        THEN '30000000-0000-0000-0000-000000000003'

    -- 13. Ctrl+Shift+R: a fé do desenvolvedor
    WHEN '10000000-0000-0000-0000-000000000013'
        THEN '30000000-0000-0000-0000-000000000001'

    -- 14. Funciona como esperado (era a América)
    WHEN '10000000-0000-0000-0000-000000000014'
        THEN '30000000-0000-0000-0000-000000000002'

    -- 15. git push --force
    WHEN '10000000-0000-0000-0000-000000000015'
        THEN '30000000-0000-0000-0000-000000000003'

    -- 16. Sai da frente da minha sprint
    WHEN '10000000-0000-0000-0000-000000000016'
        THEN '30000000-0000-0000-0000-000000000007'

    -- 17. TODO: remover gambiarra depois
    WHEN '10000000-0000-0000-0000-000000000017'
        THEN '30000000-0000-0000-0000-000000000004'

    -- 18. Os 12 trabalhos: o backlog do Jira
    WHEN '10000000-0000-0000-0000-000000000018'
        THEN '30000000-0000-0000-0000-000000000007'

    -- 19. Zeus e o DELETE sem WHERE
    WHEN '10000000-0000-0000-0000-000000000019'
        THEN '30000000-0000-0000-0000-000000000008'

    -- 20. O Príncipe e o estagiário
    WHEN '10000000-0000-0000-0000-000000000020'
        THEN '30000000-0000-0000-0000-000000000009'

    ELSE categoria_id
END
WHERE id IN (
    '10000000-0000-0000-0000-000000000001',
    '10000000-0000-0000-0000-000000000002',
    '10000000-0000-0000-0000-000000000003',
    '10000000-0000-0000-0000-000000000004',
    '10000000-0000-0000-0000-000000000005',
    '10000000-0000-0000-0000-000000000006',
    '10000000-0000-0000-0000-000000000007',
    '10000000-0000-0000-0000-000000000008',
    '10000000-0000-0000-0000-000000000009',
    '10000000-0000-0000-0000-000000000010',
    '10000000-0000-0000-0000-000000000011',
    '10000000-0000-0000-0000-000000000012',
    '10000000-0000-0000-0000-000000000013',
    '10000000-0000-0000-0000-000000000014',
    '10000000-0000-0000-0000-000000000015',
    '10000000-0000-0000-0000-000000000016',
    '10000000-0000-0000-0000-000000000017',
    '10000000-0000-0000-0000-000000000018',
    '10000000-0000-0000-0000-000000000019',
    '10000000-0000-0000-0000-000000000020'
);